        label = (
            "Claude has a question"
            if tool == "AskUserQuestion"
            else "A plan is ready for review"
            if tool == "ExitPlanMode"
            else f"Claude wants to use {req.get('displayName') or tool}"
        )
        self.notify.emit(sid, label, self.title_of(sid))
