        self._git_timer = QTimer(self)
        self._git_timer.setSingleShot(True)
        self._git_timer.setInterval(200)
        self._git_timer.timeout.connect(self._load_git)

        # ---- folder
        sec = QWidget()
        sl = vbox(sec, 8)
        sl.addWidget(_ns_label("Folder"))
