        self._laid_cols = 0
        self._laid_tiles = 0
        self._laid_two = 0
        self.now = now_ms()
        self._alive = {"on": True}
        self.destroyed.connect(lambda: self._alive.__setitem__("on", False))

        root = QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)
        head = QWidget()
        head.setFixedHeight(theme.HEADER_H)
        hl = QHBoxLayout(head)
        hl.setContentsMargins(20, 0, 20, 0)
