  process.on('SIGTERM', shutdown);
  process.on('SIGHUP', shutdown);

  const toBrowser = (why) => {
    if (why) console.log(`${why} Opening Pilcrow in your default browser instead.`);
    if (!openExternal(app.url)) console.log(`Open ${app.url} in a browser.`);
