    connect.on('error', (e) => {
      e.proxy = proxy.host;
      fail(e);
    });
    connect.on('connect', (res, socket) => {
      if (res.statusCode !== 200) {
        socket.destroy();
        return reject(new Error(`The proxy refused the tunnel (HTTP ${res.statusCode})`));
