  async contextUsage() {
    if (!this.q) return null;
    return this.q.getContextUsage({ detail: 'summary' });
  }

  async mcpStatus() {
    if (!this.q) return null;
    const list = await this.q.mcpServerStatus();
    this.setMcp(list);
