}

function publicStep(s) {
  const { tree, ...rest } = s;
  return rest;
}

export function steps(session) {
  const cwd = session.cwd;
  return { cwd: slash(cwd), enabled: !disabled.has(cwd), reason: disabled.get(cwd) || null, steps: loadSteps(cwd, session.id).map(publicStep) };
