  const move = (d: number) => {
    if (!list.length) return;
    const idx = sel === null ? list.length : list.findIndex((s) => s.n === sel);
    const next = Math.max(0, Math.min(list.length, idx + d));
    pick(next >= list.length ? null : list[next].n);
